"use strict";

// The package's whole callable API is chosen AT RUNTIME by a resolvable
// LOCAL CALL whose own body always throws -- but, unlike RWF-016's,
// RWF-017's and RWF-018's fixtures, the call sits in no VALUE position at
// all. It is a class element's COMPUTED KEY, and the element carries NO
// `static` modifier:
//
//     class Mode { [bail()] = 1; }
//
// A computed property name is evaluated by ClassDefinitionEvaluation, in
// declaration order, as each element is defined -- the key has to exist
// before the element can be installed. That is true for an INSTANCE field
// exactly as for a static one, which is precisely what makes RWF-019 a
// different rule from RWF-018 rather than a widening of it: the VALUE
// `x = bail()` of an instance field is deferred to construction (see
// `deferred-key.js`), while the KEY of that same element runs immediately.
// See fixtures/commonjs-circular-import-computed-class-key-throw-ground-truth/
// for a real node-executed proof of both halves.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw -- definitely abrupt by RWF-016's own model, unchanged.
function bail() {
  throw new Error("fast mode is not supported here");
}

// A harmless local callable, so that key evaluation ORDER is exercised
// rather than assumed.
function tag() {
  return "tag";
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Computed keys evaluate in declaration order as part of evaluating the
  // class definition, so `[tag()]` evaluates and then this necessarily
  // invokes `bail()`. It never returns, the third key is never evaluated,
  // the class definition never completes, `Mode` is never bound, and
  // module evaluation on this branch ends here.
  class Mode {
    [tag()] = "fast";
    [bail()] = 1;
    [tag()] = "never evaluated";
  }
}

module.exports = safeOp;
